/**
 * stereotype-table-llama.js
 * ---------------------------------------------------------------------
 * Top/bottom-10 stereotyped-trait table across four demographic groups
 * (AAL, WME, Woman, Man) and all three models, with a toggle across
 * three ways the group/trait association was estimated:
 *
 *   - Original: no controls. A Mann-Whitney U test, per trait per group,
 *     of that group's messages' probe scores against everyone else's
 *     ("one-vs-rest"), FDR-corrected (Benjamini-Hochberg) across traits.
 *     Value = mean_diff(group - rest). This is the only condition with
 *     real hypothesis-testing output (p/q-values, significance stars) --
 *     the two residualized conditions below are OLS point estimates with
 *     no reported SE/CI, so no significance marker is shown for them.
 *   - Length + source residualized: OLS, controlling for text length
 *     (token/char/sentence count) and source/subreddit fixed effects.
 *   - All controls residualized: OLS, additionally controlling for
 *     per-message lexical asymmetry on top of length + source.
 *
 * For the two OLS conditions, only one regression was fit per attribute
 * (race: group=AAL vs contrast=WME; gender: group=Woman vs contrast=Man)
 * -- WME's and Man's own top/bottom lists are the *same* regression,
 * sign-flipped (a trait that most favors AAL over WME is, symmetrically,
 * the trait WME is least associated with). This mirrors the sign
 * convention already used in the published length_source_residualized_
 * top_traits.md / combined_residualized_top_traits.md exports (verified
 * numerically against them when this data was built).
 *
 * Each of the two OLS conditions only has one row per trait (a single
 * group-indicator coefficient), so "top" and "bottom" for a given group
 * are two ends of the same ranked list, not independent estimates --
 * unlike "Original", where every group's ranking comes from its own
 * one-vs-rest test.
 *
 * Trait color-coding reuses the same validated 4-color Stereotype
 * Content Model dictionary palette as the other trait figures on this
 * page (trait-performance-llama.js, trait-network-gemma.js). This
 * dataset's bucket labels are ability/agency/sociability/morality;
 * "agency" is the same category called "assertiveness" elsewhere on the
 * page (confirmed by cross-checking shared trait examples), so it's
 * displayed and colored as "Assertiveness" here for consistency.
 *
 * A second segmented control below the table switches which model's
 * data is shown (Llama-3.2-1B-Instruct / Gemma-3-1B-It /
 * OLMo-2-0425-1B-Instruct). The condition toggle carries over across a
 * model switch, since it describes how the association was estimated,
 * not which model's probes it was estimated from.
 *
 * STEREOTYPE_TABLE_DATA (defined just above this IIFE) is generated by
 * figure_workspace/interactive_figures/build_stereotype_table_data.py
 * and carries all three models, keyed by model slug — regenerate that
 * JSON and paste it in to refresh this widget.
 */
(function () {
  const root = document.getElementById("stereotype-table-llama");
  if (!root || typeof STEREOTYPE_TABLE_DATA === "undefined") return;

  const MODEL_ORDER = STEREOTYPE_TABLE_DATA.modelOrder;
  let modelSlug = MODEL_ORDER[0];

  function activeModel() {
    return STEREOTYPE_TABLE_DATA.models[modelSlug];
  }

  const CONDITIONS = ["original", "length_source", "combined"];

  const BUCKET_LABEL = {
    sociability: "Sociability",
    morality: "Morality",
    agency: "Assertiveness",
    ability: "Ability",
  };
  // Same validated 4-color set used by trait-performance-llama.js /
  // trait-network-gemma.js, keyed here by this dataset's bucket names.
  const BUCKET_COLOR = {
    sociability: { light: "#2a78d6", dark: "#3987e5" },
    morality: { light: "#eda100", dark: "#c98500" },
    agency: { light: "#e87ba4", dark: "#d55181" },
    ability: { light: "#008300", dark: "#008300" },
  };
  // Same hues as RGB triples, for the translucent full-cell background wash
  // below -- a low alpha over the page's paper/ink surface keeps body text
  // legible while still reading as "this cell belongs to this dictionary"
  // at a glance, rather than relying on a small dot.
  const BUCKET_RGB = {
    sociability: { light: [42, 120, 214], dark: [57, 135, 229] },
    morality: { light: [237, 161, 0], dark: [201, 133, 0] },
    agency: { light: [232, 123, 164], dark: [213, 81, 129] },
    ability: { light: [0, 131, 0], dark: [0, 131, 0] },
  };

  function isDark() {
    return document.documentElement.getAttribute("data-theme") === "dark";
  }
  function bucketColor(bucket) {
    const c = BUCKET_COLOR[bucket];
    return c ? c[isDark() ? "dark" : "light"] : "var(--color-ink-faint)";
  }
  function bucketBackground(bucket) {
    const rgb = BUCKET_RGB[bucket];
    if (!rgb) return "";
    const [r, g, b] = rgb[isDark() ? "dark" : "light"];
    // Dark surfaces need a stronger alpha for the tint to read at the same
    // perceived strength as on the light "paper" background.
    const alpha = isDark() ? 0.28 : 0.16;
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }

  let condition = "original";

  // ---- tooltip -----------------------------------------------------
  const tooltip = document.createElement("div");
  tooltip.style.cssText =
    "position:absolute;pointer-events:none;z-index:5;opacity:0;transition:opacity .1s ease;" +
    "background:var(--color-ink);color:var(--color-bg);font-family:var(--font-sans);" +
    "font-size:0.78rem;line-height:1.4;padding:0.45em 0.65em;border-radius:4px;max-width:260px;";
  root.style.position = "relative";
  root.appendChild(tooltip);

  function showTooltip(html, evtX, evtY) {
    tooltip.innerHTML = html;
    const rect = root.getBoundingClientRect();
    tooltip.style.left = evtX - rect.left + 14 + "px";
    tooltip.style.top = evtY - rect.top + 10 + "px";
    tooltip.style.opacity = "1";
  }
  function hideTooltip() {
    tooltip.style.opacity = "0";
  }

  function fmt(v) {
    return (v >= 0 ? "" : "\u2212") + Math.abs(v).toFixed(3);
  }

  function pStr(p) {
    if (p < 0.001) return "p < 0.001";
    return "p = " + p.toFixed(3);
  }

  function traitCell(entry, cond) {
    const span = document.createElement("span");
    span.className = "trait-cell";

    span.appendChild(document.createTextNode(entry.trait));

    const value = document.createElement("span");
    value.className = "trait-value";
    value.textContent = "(" + fmt(entry.value) + ")";
    span.appendChild(value);

    if (cond.hasSignificance && entry.sig) {
      const sig = document.createElement("sup");
      sig.className = "trait-sig";
      sig.textContent = entry.sig;
      span.appendChild(sig);
    }

    const bucketLabel = BUCKET_LABEL[entry.bucket] || entry.bucket;
    let tip =
      "<b>" + entry.trait + "</b><br>" + bucketLabel + " (" + entry.dir + ")<br>" +
      cond.valueLabel + ": " + fmt(entry.value);
    if (cond.hasSignificance) {
      tip += "<br>" + pStr(entry.p) + " (FDR q " + (entry.q < 0.001 ? "< 0.001" : "= " + entry.q.toFixed(3)) + ")";
      tip += "<br>n(group) = " + entry.n_group + ", n(rest) = " + entry.n_rest;
    } else if (entry.n) {
      tip += "<br>n = " + entry.n + ", dof = " + entry.dof;
    }
    span.addEventListener("mousemove", (evt) => showTooltip(tip, evt.clientX, evt.clientY));
    span.addEventListener("mouseleave", hideTooltip);

    return span;
  }

  function buildTable(direction, condKey) {
    const model = activeModel();
    const groups = model.groups; // ["AAL","WME","Woman","Man"]
    const cond = model.conditions[condKey];
    const table = document.createElement("table");
    table.className = "stereotype-table";

    const thead = document.createElement("thead");
    const headRow = document.createElement("tr");
    ["Rank"].concat(groups).forEach((label) => {
      const th = document.createElement("th");
      th.textContent = label;
      headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);

    const tbody = document.createElement("tbody");
    for (let i = 0; i < model.topN; i++) {
      const tr = document.createElement("tr");
      const rankTd = document.createElement("td");
      rankTd.textContent = String(i + 1);
      tr.appendChild(rankTd);
      groups.forEach((g) => {
        const td = document.createElement("td");
        const entry = cond.groups[g][direction][i];
        if (entry) {
          td.style.backgroundColor = bucketBackground(entry.bucket);
          td.style.borderLeft = "3px solid " + bucketColor(entry.bucket);
          td.appendChild(traitCell(entry, cond));
        }
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    return table;
  }

  function render() {
    root.querySelectorAll(".stereotype-table-panel").forEach((el) => el.remove());

    function scrollWrap(table) {
      const wrap = document.createElement("div");
      wrap.className = "stereotype-table-scroll";
      wrap.appendChild(table);
      return wrap;
    }

    const topPanel = document.createElement("div");
    topPanel.className = "stereotype-table-panel";
    const topHeading = document.createElement("p");
    topHeading.className = "stereotype-table-heading";
    topHeading.textContent = "Most associated";
    topPanel.appendChild(topHeading);
    topPanel.appendChild(scrollWrap(buildTable("top", condition)));
    root.appendChild(topPanel);

    const bottomPanel = document.createElement("div");
    bottomPanel.className = "stereotype-table-panel";
    const bottomHeading = document.createElement("p");
    bottomHeading.className = "stereotype-table-heading";
    bottomHeading.textContent = "Least associated";
    bottomPanel.appendChild(bottomHeading);
    bottomPanel.appendChild(scrollWrap(buildTable("bottom", condition)));
    root.appendChild(bottomPanel);
  }

  // ---- segmented controls ---------------------------------------------
  // Shared wiring for any segmented control keyed off a data-* attribute
  // on `root` pointing at the control's element id (the pattern this
  // widget already used for the condition toggle) — reused below for
  // both the condition control and the new bottom model control.
  function wireSegmentedControl(rootDataAttr, btnDataAttr, onSelect) {
    const controlId = root.getAttribute(rootDataAttr);
    const control = controlId ? document.getElementById(controlId) : null;
    if (!control) return;

    const thumb = control.querySelector(".segmented-thumb");
    const buttons = Array.from(control.querySelectorAll(".segmented-btn"));

    function moveThumb() {
      const active = control.querySelector(".segmented-btn.is-active");
      if (!active || !thumb) return;
      thumb.style.width = active.offsetWidth + "px";
      thumb.style.transform = "translateX(" + active.offsetLeft + "px)";
    }

    buttons.forEach((btn) => {
      btn.addEventListener("click", () => {
        if (btn.classList.contains("is-active")) return;
        buttons.forEach((b) => {
          b.classList.remove("is-active");
          b.setAttribute("aria-selected", "false");
        });
        btn.classList.add("is-active");
        btn.setAttribute("aria-selected", "true");
        moveThumb();
        onSelect(btn.getAttribute(btnDataAttr));
        render();
      });
    });

    window.addEventListener("resize", moveThumb);
    requestAnimationFrame(moveThumb);
  }

  wireSegmentedControl("data-control", "data-condition", (value) => {
    condition = value;
  });

  // Bottom model control: which model's data is shown. The condition
  // toggle above is left untouched by a model switch, since it describes
  // how the association was estimated, not which model it came from.
  wireSegmentedControl("data-model-control", "data-model", (value) => {
    modelSlug = value;
  });

  render();

  // Trait-dot colors are baked in at build time (bucketColor read once
  // per cell); rebuild on dark-mode toggle so they follow the theme.
  const observer = new MutationObserver(render);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
})();
